'use strict';
const el = id => document.getElementById(id);
let token, uncertainHandle = null, handle = null, approvedRequest = null, generation = 0, busy = false, displayed = null;
const logs = [];
function log(text) { logs.unshift(new Date().toISOString() + ' ' + text); logs.splice(24); el('log').textContent = logs.join('\n'); }
function show(value) { displayed = value; el('evidence').textContent = JSON.stringify(value, null, 2); el('download').disabled = false; if (value.snapshot) state(value.snapshot); }
function state(value) { el('state').textContent = JSON.stringify(value, null, 2); if (value.state) el('old').value = value.state.accountEnding; }
function disableApproval() { for (const id of ['execute','revoke','reconcile']) el(id).disabled = true; }
function invalidate() { generation++; handle = null; approvedRequest = null; disableApproval(); if (uncertainHandle) el('reconcile').disabled = false; el('checks').replaceChildren(); el('status').textContent = 'Changed input — prior result is stale. Evaluate again.'; log('Browser approval discarded; server still enforces signed binding.'); }
for (const id of ['scenario','supplier','ending','amount']) el(id).addEventListener('input', invalidate);
async function call(path, body) { const r = await fetch('/api/' + path, { method:'POST', headers:{'content-type':'application/json','x-atg-demo-token':token}, body:JSON.stringify(body) }); const value = await r.json(); if (!r.ok) throw Error(value.error || 'Local request failed'); return value; }
function request() { const text = el('amount').value.trim(); if (!/^(?:0|[1-9]\d{0,5})(?:\.\d{1,2})?$/.test(text)) throw Error('Enter a positive fictional amount with at most two decimal places.'); const amountMinorUnits = Math.round(Number(text)*100); if (!Number.isSafeInteger(amountMinorUnits) || amountMinorUnits <= 0 || amountMinorUnits > 10000000) throw Error('Demo amount must be above zero and at most £100,000.'); return { scenarioId:el('scenario').value,supplierReference:el('supplier').value,proposedAccountEnding:el('ending').value,amountMinorUnits }; }
async function operation(fn) { if (busy) return; busy = true; el('evaluate').disabled = true; el('editState').disabled = true; try { await fn(); } catch(e) { disableApproval(); el('status').textContent = 'Request failed — execution disabled. Inspect the local session; do not retry an uncertain write.'; log(e.message); } finally { busy = false; el('evaluate').disabled = !token; el('editState').disabled = !token; if (uncertainHandle) el('reconcile').disabled = false; } }
el('evaluate').onclick = () => operation(async () => { disableApproval(); const seq = generation; const req = request(); handle = null; approvedRequest = null; const value = await call('approve',{request:req}); if (seq !== generation) { log('Ignored stale evaluation response.'); return; } show(value); el('status').textContent = value.outcome + ' — ' + value.reason; el('checks').replaceChildren(); for (const check of value.decision.controls) { const div = document.createElement('div'); div.className='check '+(check.passed?'pass':'fail'); div.textContent=(check.passed?'PASS: ':'REFUSED: ')+check.control+' — '+check.detail; el('checks').append(div); } if (value.executionAvailable) { handle=value.approvalId; approvedRequest=req; el('execute').disabled=false; el('revoke').disabled=false; } if (uncertainHandle) el('reconcile').disabled=false; log(value.outcome); });
el('execute').onclick = () => operation(async () => { if (!handle || !approvedRequest) return; const id=handle; disableApproval(); const value=await call('execute',{approvalId:id,request:request(),fault:el('fault').value}); show(value); el('status').textContent=value.outcome+' — '+value.reason; if (value.outcome==='UNKNOWN') { uncertainHandle=id; el('reconcile').disabled=false; } log('Execution result: '+value.outcome+'. No automatic retry.'); });
el('revoke').onclick = () => operation(async () => { if(!handle)return; const value=await call('revoke',{approvalId:handle}); disableApproval(); show(value); el('status').textContent='Demo revocation: '+value.revoked; });
el('editState').onclick = () => operation(async () => { const value=await call('state-edit',{}); state(value); el('status').textContent='Destination version edited. Existing authority will be checked and refused at execution.'; log('Synthetic version incremented without resetting state.'); });
el('reconcile').onclick = () => operation(async () => { if(!uncertainHandle)return; disableApproval(); const value=await call('reconcile',{approvalId:uncertainHandle}); if(value.outcome==='EXECUTED') uncertainHandle=null; show(value); el('status').textContent=value.outcome+' — '+value.reason; log('Read same-process record; no external evidence claim.'); });
el('download').onclick=()=>{ const url=URL.createObjectURL(new Blob([JSON.stringify(displayed,null,2)],{type:'application/json'})); const a=document.createElement('a'); a.href=url; a.download='payeeshield-synthetic-evidence.json'; a.click(); setTimeout(()=>URL.revokeObjectURL(url),1000); };
(async()=>{try{const r=await fetch('/api/bootstrap');if(!r.ok)throw Error('Local server required');const data=await r.json();token=data.token;for(const id of data.scenarios){const o=document.createElement('option');o.value=id;o.textContent=id.replaceAll('_',' ');el('scenario').append(o);}state(data.snapshot);el('status').textContent='Ready — registered fictional fixtures only.';el('evaluate').disabled=false;el('editState').disabled=false;}catch(e){el('status').textContent='Start npm run demo:payeeshield from the repository. This page requires its local ATG server.';}})();
